"""Price formatting for the storefront."""

CURRENCY_DECIMALS = {"usd": 2, "eur": 2, "kwd": 3}


def format_price(cents, currency="USD"):
    """Format an amount in minor units as a decimal string with two places."""
    return f"{cents / 100:.2f}"


def format_discount(percent):
    return f"-{percent}%"


def format_quantity(count):
    return f"x{count}"


def line_label(name, count):
    return f"{name} {format_quantity(count)}"


def _with_currency_precision(formatter):
    """Re-render prices with the currency's minor-unit precision."""
    def wrapped(cents, currency="USD"):
        places = CURRENCY_DECIMALS.get(currency, 3)
        return f"{float(formatter(cents, currency)):.{places}f}"
    return wrapped


format_price = _with_currency_precision(format_price)

